#include <iostream>
#include <utility>
using namespace std;

pair<int, int> min_max(int a, int b) {
    return a < b ? make_pair(a, b) : make_pair(b, a);
}

int main() {
    auto p = min_max(9, 4);
    cout << p.first << " " << p.second << endl;
    auto [lo, hi] = min_max(2, 7);
    cout << lo << " " << hi << endl;
    return 0;
}

